A=json.loads((F/'additions.json').read_text()); byid={x['card']['id']:x for x in A}
# Each replacement is individually authored after reading its existing question/background.
R={
'0164':('自分が支えた企画で別の人だけが有名になった。十分な報酬は得たが、仕事への気持ちはどう変わる？','仮の共同成果。生活の対価は満たされても、職業として自分の名が残ることに別の意味を見いだす人もいる。','報酬と職業人生に残る承認を分ける。'),
'0180':('仕事の依頼を待つ暮らしが長く続き、人生の予定を自分で選びにくい。作業のない時間を自由だと言われたら何を伝える？','仮の働き方。待機の法的な扱いとは別に、仕事を逃す不安で約束や暮らしを選べない本人の時間を問う。','仕事待ちに使う人生の時間を聞く。'),
'0185':('家が仕事の場所になり、何年も暮らしから仕事が離れない。収入も仕事も好きでも、自分が生きる場所に何を取り戻したい？','架空の在宅勤務。配置の工夫より、好きな職業が私生活の中心を占めた本人の人生の境界を考える。','好きな労働が占める生活の意味を聞く。'),
'0193':('職場では明るい役を長く務め、自分の弱さを出せない。仲間との関係はよくても、その働く自分をどこまで続けたい？','架空の職場。あだ名の好みより、職業の中で演じてきた人格と自分の気持ちの違いを考える。','仕事で演じ続ける自己を聞く。'),
'0208':('人生をかけた仕事が本当に人の役に立つか分からなくなった。仕事を止めれば仲間も困るなら、何を確かめるために時間を使う？','架空の職業。価値を失ったと確定せず、自分の信じた意義と、働き続ける人の責任を比べる。','働く意義を疑う本人の責任を聞く。'),
'0213':('自分の代表作として広く売れた物に、納得できない細部がある。使う人は満足していても、作った自分の何を残したい？','架空の作品。安全上の欠点はなく、自分の職業人生に残る成果と受け手の満足の基準を分ける。','代表作を引き受ける本人の基準を聞く。'),
'0216':('長く育てた相手を助けたら、もう自分で担いたいと拒まれた。相手を支えるために続けた仕事の関係を、何に変えたい？','仮の育成後。助言の方法より、支える役として築いた自分の職業と相手の独立を考える。','支える職業の関係を更新する本人を聞く。'),
'0217':('人生の途中で新しい仕事へ移りたいが、学ぶ間は仲間の支えが必要になる。昔の熟練を離れてまで、どんな自分になりたい？','架空の転換。技能練習の段取りではなく、積み重ねた職業を変える意味と他者へ頼る責任を問う。','職業を変える自分と支えの意味を聞く。'),
'0218':('自分の力量がまだ足りない大きな仕事で、相手は暮らしの将来まであなたに託したいと言う。学びながら担うことを、何と説明する？','架空の依頼。成果を保証できないことと、信頼された本人がどこまで責任を引き受けるかを比べる。','他者の未来を託される不確かな自分を聞く。'),
'0219':('急な仕事を待つ役を長く務め、自分の人生が人の予定のためになっている。断れば別の人が担う時、自分は何を終えたい？','架空の職場。依頼を一度断る手順より、担い続けた本人の時間を選び直す責任を考える。','人の予定に使った人生を選び直す。'),
'0221':('最後の作品として自分の名が残る仕事に、納得できない部分がある。客は今の形を望む時、完成の何を引き受けたい？','架空の納品。細かな締切の調整より、本人の職業の区切りと受け手が望む完成を考える。','職業の最後の成果を完成とする意味を聞く。'),
'0224':('仲間の工夫を広めれば、自分の大きな仕事も実現できる。相手はまだ公にしたくない時、自分の機会を待つ理由は何？','架空の共同事業。秘密の権利の判定ではなく、長く望んだ職業の機会と他者の創作の時間を比べる。','自分の大きな機会と他者の技能を聞く。'),
'0225':('自分を信頼する家族へ、老後の暮らしを変える品物を売った。相手が後悔している時、商いと家族の何を自分の責任にする？','架空の販売。欠陥や違法な勧誘は確定せず、家族の将来の選択に関わった専門家の本人を考える。','家族の未来に関わる商いの責任を聞く。'),
'0227':('客にいつでも応えてきたため、好きだった仕事を離れたくなっている。関係が続かないかもしれなくても、何を自分に戻したい？','仮の商い。時間外のルールだけでなく、仕事を愛した本人の生活を回復する意味を問う。','商いへの愛着を失う本人の境界を聞く。'),
'0240':('人が学べる会社を作りたいと思い、育てた人が次々去った。残る人の生活もある中、自分の信じた育成をどう続けたい？','架空の会社。研修費の効率より、創業した本人の理念と、会社を共に続ける人への責任を比べる。','人を育てる経営の信念の持続を聞く。'),
'0241':('自分が期待して採った人が、その仕事を選んだことを後悔している。見込みを否定される怖さがあっても、相手の人生へ何を引き受ける？','架空の採用後。本人の進路を代わりに決めず、自分が期待を伝えて生んだ機会と責任を考える。','進路へ期待を託した採用者を聞く。'),
'0245':('自分が人生をかけた会社へ、人を招きたい。自分にも薦めにくい面がある時、誇りと率直さの何を伝える？','架空の採用。問題を一方的に断定せず、自分が築いた場へ他者の職業人生を誘う意味を考える。','築いた会社へ人を招く自分の率直さを聞く。'),
'0248':('人生の多くを使って覚えた技能を、新しい人は道具で簡単に学べる。自分の苦労を繰り返させず、何を価値として渡したい？','仮の道具導入。教育の手順より、自分が費やした時間の意味を次の人の自由と分ける。','自分の職業の苦労を継ぐ意味を聞く。'),
'0252':('会社の未来を託すつもりで育てた人が、別の会社を望む。送り出せば自分の引退も難しい時、何を本人の自由と思う？','仮の後継者の退出。担当の遅れだけでなく、自分が終える予定だった職業の時間へ影響する。','自分の引退が変わる後継者の退出を聞く。'),
'0255':('会社を一緒に支えた仲間へ約束した評価が、他の人の貢献を知って揺らいだ。信じてもらった自分は何を約束し直せる？','架空の評価。長い関係で生んだ待遇への期待と、これから他者に示す公平を比較する。','共同者への評価の約束を変える責任を聞く。'),
'0258':('過去の事業の失敗から、会社の余剰を残しておきたい。働く仲間が今の報酬を望む時、自分の恐れをどこまで経営の理由にする？','架空の利益配分。未来の不安を予測と決めず、決める本人の経験と現在の貢献を比べる。','失敗した経験を背負う分配者を聞く。'),
'0259':('自分が人生の機会だと任せた仕事で、部下が失敗し自信を失った。引き受けるよう促した自分は、何を今から担える？','架空の委任。失敗を本人だけに置かず、期待を伝えた立場が相手の職業へ残した影響を考える。','挑戦を促した本人の残る責任を聞く。'),
'0408':('自分は優遇されて買える物を、同じように必要な人は高くて買えない。説明はあるが、その優遇を受ける自分をどう考える？','架空の販売。無償で譲る義務は置かず、自分に有利な条件でも守りたい公平の意味を問う。','必要が同じ他者より優遇される自己を聞く。'),
'0410':('将来の暮らしのため大きな買い物をしたが、人生の望みが変わり使えない。費やした時間と財産を、何が失敗だと思う？','架空の購入後。品物に欠点はなく、金額の損失と、自分の将来を描いて備えた意味を分ける。','未来を備えた消費を選び直す本人を聞く。'),
'0412':('自分が大切に生きるための支出を、援助する人はぜいたくだと言う。援助が変わるかもしれなくても、何を譲れない？','架空の私的援助。公的な給付の条件ではなく、家計を支える相手と本人の生活の意味を比べる。','援助下の消費の尊厳を聞く。'),
'0417':('長く人生の節目で買い物をした店が、自分に不利な条件を伝えなかった。品物は大切でも、関係の何が戻らないと思う？','架空の取引。違法性は未確定で、商品の満足とは別に商いへ託した信頼を考える。','大切な消費の相手への信頼の喪失を聞く。'),
'0421':('老後の暮らしに充てるつもりで契約したサービスが終了する。支払った額は戻るが、準備した人生の予定の何を失う？','仮の契約終了。実際の返金制度ではなく、お金が戻ることと将来の選択を作り直すことを分ける。','返金で戻らない将来の備えを聞く。'),
'0426':('将来のために備え続け、望んだことをしないまま年を重ねた。備えが役立つとしても、これからの財産を何に使いたい？','仮の家計。節約の成功と、その間に使わず残した人生の機会を比べる。','備え続けた人生の使い道を聞く。'),
'0435':('人生をかけて集めた物を人へ譲りたいが、使い方を変えてほしくない。引き継ぐ人の自由が必要なら何を手放す？','架空の譲渡。単なる貸し物の条件ではなく、財産へ重ねた自分の生涯の期待を問う。','生涯の収集財産を渡す意味を聞く。'),
'0437':('人生の成功の証として高価な物を買いたい。人に認められなくても、何を自分が成し遂げた証にしたい？','仮の記念消費。高いほど成功とは置かず、財産が担う本人の達成の意味を考える。','消費を人生の成功の象徴にする本人を聞く。'),
'0438':('家族に残すはずだった記念の財産を、自分の生活のため売りたい。期待が戻らないとしても、何を受け継いだ責任と思う？','架空の処分。法的に売れる本人に、家族の記憶と今の家計の必要が重なる。','遺産を生活へ換える責任を聞く。'),
'0440':('人生の大きな資金を、自分が誤解した条件で使った。店の説明は十分だったと思う時、選んだ自分を何で責めずに振り返る？','仮の契約。金融の助言や法的責任を決めず、回復しにくい選択の失敗を引き受ける意味を問う。','大きな消費の誤解を引き受ける本人を聞く。'),
'0442':('消費の価値観を共有してきた仲間から、家計のため選んだ食品を否定された。自分の生活を知ってもらうため何を話す？','仮の消費。道徳の低さと決めず、共に信じた選び方を続けられない本人の関係を考える。','消費の信念でつながる仲間との境界を聞く。'),
'0444':('自分の商いは親しい人だけの低い価格で続いたが、他の客には納得できないと言われた。大切な関係と公平を、何で変えたい？','仮の販売。単発の割引より、これまでの商いの関係を支えた値付けを選び直す場面。','価格で支えた商いの関係を聞く。'),
'0447':('自分の信念に合うと思って買った物が、暮らしには使いにくい。返せるとしても、選んだ価値をどこまで自分で担いたい？','仮の購入。返品の可否を説明せず、自分が望んだ消費の理念と使える生活を比べる。','消費の理念の不便さを引き受ける本人を聞く。'),
'0448':('大切な人との関係を保つため贈り物を続けてきた。相手は欲しくないと言う時、お金で示した自分の気持ちをどう手放す？','架空の贈与。高額にするだけの問いでなく、消費へ託した長い関係の維持を考える。','贈与に託した関係を選び直す本人を聞く。'),
'0451':('自分が信頼してすすめた大きな買い物を、友人は後悔している。自分の利益はなくても、相手が託した信頼をどこまで担う？','仮の推薦。詐欺や欠陥は置かず、販売者とは別に関係の中で生んだ期待を考える。','生活を変える消費の推薦の責任を聞く。'),
'0459':('家族の遺産を公平に分ける役を頼まれたが、自分が生涯大切にしたい物が一つある。他の人も望むなら何を諦められる？','架空の分配。単に欲しいと言う順序ではなく、調整役自身の人生の記憶と公平を比べる。','利害を持つ遺産の調整者の放棄を聞く。'),
'0461':('長く自分を支えた客には買えない値段でも、自分の作品が売れるようになった。商いが変わる時、何を成功と呼びたい？','仮の販売。単なる値上げの判断ではなく、自分の名と、支えた人へ届く仕事の関係を問う。','成功が変える商いの本人を聞く。'),
'0463':('家族と持つ記念の財産を売る役になった。自分はこれからの生活に使いたいが、他の人は未来へ残したい。誰の時間を優先する？','仮の共有解消。売る権利ではなく、同じ財産に重ねた現在と未来の意味を考える。','自分の未来を望む財産整理者を聞く。'),
'0470':('友人の暮らしを支えるため安く売ってきたが、自分の商いが続かない。友人が買えなくなっても、何を今の関係で終えたい？','架空の価格変更。価格の伝え方だけでなく、消費で支えた相手と自分の生業の限界を比べる。','友人の消費を支え続けた商いの限界を聞く。'),
'0701':('家族の思い出の家を自分が管理してきたが、今の人生へ時間を戻したい。部屋を残してほしい人へ何を終えると伝える？','仮の住居整理。片付けの方法より、記念の家を維持してきた本人の未来と共有した記憶を比べる。','家族の記念住宅を支える本人の終了を聞く。'),
}
log=[]
for num,(q,d,r) in R.items():
 id='exp26-livelihood-'+num;x=byid[id];c=x['card'];old={'question':c['question'],'detail':c.get('detail',{}).get('text'),'reason':x['reason']}
 file,line=x['editorial']['source_row'].rsplit(':',1);p=F/file;rows=p.read_text().splitlines();v=rows[int(line)-1].split('|')
 assert len(v)==7 and v[1]==c['question'],(id,file,line)
 v[1]=q;v[2]=d;v[6]=r
 rows[int(line)-1]='|'.join(v);p.write_text('\n'.join(rows)+'\n')
 log.append({'id':id,'before':old,'after':{'question':q,'detail':d,'reason':r},'review_reason':'普通の段取りだけに留めず、本人の人生・信念・関係・引き受ける責任を固有に明示。'})
(F/'review-revisions.json').write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n')
print(len(log),'self-review revisions recorded')
